import React, { useEffect, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import {
  getHomePath,
  hasValidAuthToken,
  isPermissionsReady,
  PermissionsBootstrapLoading,
} from '@linm-soft-org/linm-web-common-components';
import { navigateInAppPath } from '../../router/navigateInAppPath';

interface PublicRouteProps {
  children: React.ReactNode;
  redirectTo?: string;
}
/**
 * Public routes (login). When authenticated, redirect via shell URL (navigateToUrl)
 * so the correct MFE mounts — not MemoryRouter-only Navigate.
 */
export const PublicRoute: React.FC<PublicRouteProps> = ({ children }) => {
  const navigate = useNavigate();
  const { isAuthenticated, user, requirePasswordChange } = useAppSelector((state) => state.auth);
  const location = useLocation();
  const tokenExists = hasValidAuthToken();
  const permissionsReady = isPermissionsReady();

  const destination = useMemo(() => {
    if (!isAuthenticated || !tokenExists || requirePasswordChange) return null;

    const from = (location.state as { from?: { pathname?: string } })?.from?.pathname;

    if (user?.defaultMenuUrl) return user.defaultMenuUrl;
    if (from) return from;
    if (permissionsReady) {
      return getHomePath(user?.role, user?.package, undefined, user?.packageDefaultUrl);
    }
    return null;
  }, [
    isAuthenticated,
    tokenExists,
    requirePasswordChange,
    location.state,
    user?.defaultMenuUrl,
    user?.role,
    user?.package,
    user?.packageDefaultUrl,
    permissionsReady,
  ]);

  useEffect(() => {
    if (!destination) return;
    navigateInAppPath(destination, navigate, { replace: true });
  }, [destination, navigate]);

  if (isAuthenticated && tokenExists && !requirePasswordChange) {
    if (!destination) {
      return <PermissionsBootstrapLoading />;
    }
    return null;
  }

  return <>{children}</>;
};
