import { linmLogo128 } from '@linm-soft-org/linm-web-common-components';
import { resolveShellIcon } from '../config/shellBranding';

const BRANDING_KEY = 'company_branding';

export interface CompanyBranding {
  /** Company code (tenant key) — same as `code`. */
  id: string;
  code: string;
  name: string;
  shortName?: string;
  logoUrl?: string;
}

export function normalizeCompanyCode(code: string): string {
  return code.trim().toUpperCase();
}

export const companyBrandingService = {
  get(): CompanyBranding | null {
    try {
      const raw = localStorage.getItem(BRANDING_KEY);
      return raw ? (JSON.parse(raw) as CompanyBranding) : null;
    } catch {
      return null;
    }
  },

  set(b: CompanyBranding): void {
    localStorage.setItem(BRANDING_KEY, JSON.stringify(b));
  },

  clear(): void {
    localStorage.removeItem(BRANDING_KEY);
  },

  /** Returns company logo, or /icons/{folder}/logo-128.png, or Linm default. */
  getInstallLogo(): string {
    return this.get()?.logoUrl ?? resolveShellIcon(linmLogo128);
  },

  /** Fetch by company code, store and return. */
  async fetchByCode(code: string, apiUrl: string): Promise<CompanyBranding | null> {
    const normalized = normalizeCompanyCode(code);
    if (!normalized) return null;

    try {
      const res = await fetch(`${apiUrl}/companies/by-code/${encodeURIComponent(normalized)}`);
      if (!res.ok) return null;
      const json = (await res.json()) as { data?: Record<string, unknown> } & Record<string, unknown>;
      const data = (json.data ?? json) as {
        id?: string;
        code?: string;
        name: string;
        shortName?: string;
        logoUrl?: string;
      };
      const resolvedCode = normalizeCompanyCode(data.code ?? data.id ?? normalized);
      const branding: CompanyBranding = {
        id: resolvedCode,
        code: resolvedCode,
        name: data.name,
        shortName: data.shortName,
        logoUrl: data.logoUrl,
      };
      this.set(branding);
      return branding;
    } catch {
      return null;
    }
  },
};
