/** ERP search normalize — search-input.md SSOT (case/space/diacritic insensitive). */
export function normalizeSearchText(value?: string): string {
  return (value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

/** Compact form for remote API search (no spaces). */
export function normalizeSearchTextCompact(value?: string): string {
  return normalizeSearchText(value).replace(/\s+/g, '');
}
